use vstd::prelude::*;

verus! {

/// Spec-level description of the desired meshgrid shape/content.
///
/// Note: for `f32`, Verus can reason about equality of values stored in vectors
/// as uninterpreted values; we avoid any arithmetic reasoning.
spec fn meshgrid_spec_x(
    x: Seq<f32>,
    y: Seq<f32>,
    mx: Seq<Seq<f32>>,
) -> bool {
    mx.len() == y.len()
    && forall|i: int|
        0 <= i < y.len() ==>
            mx[i].len() == x.len()
            && forall|j: int|
                0 <= j < x.len() ==> mx[i][j] == x[j]
}

spec fn meshgrid_spec_y(
    x: Seq<f32>,
    y: Seq<f32>,
    my: Seq<Seq<f32>>,
) -> bool {
    my.len() == y.len()
    && forall|i: int|
        0 <= i < y.len() ==>
            my[i].len() == x.len()
            && forall|j: int|
                0 <= j < x.len() ==> my[i][j] == y[i]
}

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        // shape + contents for both output matrices
        meshgrid_spec_x(x@, y@, result.0@.map_values(|row: Vec<f32>| row@)),
        meshgrid_spec_y(x@, y@, result.1@.map_values(|row: Vec<f32>| row@)),
{
    let nx = x.len();
    let ny = y.len();

    let mut mx: Vec<Vec<f32>> = Vec::new();
    let mut my: Vec<Vec<f32>> = Vec::new();

    let mut i: usize = 0;
    while i < ny
        invariant
            i <= ny,
            nx == x.len(),
            ny == y.len(),
            mx.len() == i,
            my.len() == i,
            // All rows built so far satisfy the spec:
            forall|r: int|
                0 <= r < i as int ==>
                    mx@[r].len() == nx
                    && (forall|c: int|
                        0 <= c < nx as int ==> mx@[r][c] == x@[c]),
            forall|r: int|
                0 <= r < i as int ==>
                    my@[r].len() == nx
                    && (forall|c: int|
                        0 <= c < nx as int ==> my@[r][c] == y@[r]),
        decreases ny - i,
    {
        // Build one row for mx and one row for my
        let mut rowx: Vec<f32> = Vec::new();
        let mut rowy: Vec<f32> = Vec::new();

        let mut j: usize = 0;
        while j < nx
            invariant
                j <= nx,
                nx == x.len(),
                ny == y.len(),
                rowx.len() == j,
                rowy.len() == j,
                // row content matches prefix of x and constant y[i]
                forall|c: int|
                    0 <= c < j as int ==> rowx@[c] == x@[c],
                forall|c: int|
                    0 <= c < j as int ==> rowy@[c] == y@[i as int],
            decreases nx - j,
        {
            rowx.push(x[j]);
            rowy.push(y[i]);
            j += 1;
        }

        // Now rowx/rowy have length nx and satisfy desired content for this i
        mx.push(rowx);
        my.push(rowy);

        i += 1;
    }

    // Return the pair
    (mx, my)
}

} // verus!

